#!/usr/bin/env python3
# NISCAYA MAKASSAR patch 0003: koreksi otomatis nama merek salah ketik (fuzzy ke merek asli)
import sys, json
path = sys.argv[1]
src = open(path, encoding="utf-8").read()
if "function autoFixMerek" in src:
    print("0003: sudah terpasang"); sys.exit(0)
crlf = "\r\n" in src
if crlf: src = src.replace("\r\n", "\n")
EDITS = json.loads('[["const MEREK_ALIAS = {AXIO:\'AXIOO\', AXOO:\'AXIOO\', DELLL:\'DELL\', LENIOVO:\'LENOVO\', LENONO:\'LENOVO\', LEVONO:\'LENOVO\', THOSIBA:\'TOSHIBA\', TOSHOBA:\'TOSHIBA\', COMPEAQ:\'COMPAQ\', SURFACE:\'MICROSOFT\'};\\nfunction normMerek(m){ const k = String(m||\'\').trim().toUpperCase().replace(/\\\\s+/g,\' \'); return MEREK_ALIAS[k] || k || \'LAINNYA\'; }", "const MEREK_KNOWN = [\'ACER\',\'ADVAN\',\'ALIENWARE\',\'APPLE\',\'ASUS\',\'AVITA\',\'AXIOO\',\'CHUWI\',\'COMPAQ\',\'DELL\',\'EVERCOSS\',\'FUJITSU\',\'GIGABYTE\',\'HP\',\'HUAWEI\',\'IBM\',\'INFINIX\',\'LENOVO\',\'LG\',\'MICROSOFT\',\'MSI\',\'NEC\',\'PANASONIC\',\'RAZER\',\'SAMSUNG\',\'SONY\',\'TOSHIBA\',\'VAIO\',\'XIAOMI\',\'ZYREX\'];\\nconst MEREK_ALIAS = {SURFACE:\'MICROSOFT\', MACBOOK:\'APPLE\', MAC:\'APPLE\', THINKPAD:\'LENOVO\', IDEAPAD:\'LENOVO\', LEGION:\'LENOVO\', ROG:\'ASUS\', VIVOBOOK:\'ASUS\', ZENBOOK:\'ASUS\', PAVILION:\'HP\', ELITEBOOK:\'HP\', PROBOOK:\'HP\', \'HEWLETT PACKARD\':\'HP\', LATITUDE:\'DELL\', INSPIRON:\'DELL\', VOSTRO:\'DELL\', ASPIRE:\'ACER\', PREDATOR:\'ACER\', NITRO:\'ACER\'};\\nfunction merekDist(a, b){\\n  const d = []; for(let i=0;i<=a.length;i++){ d[i] = [i]; } for(let j=0;j<=b.length;j++) d[0][j] = j;\\n  for(let i=1;i<=a.length;i++) for(let j=1;j<=b.length;j++){\\n    const c = a[i-1]===b[j-1] ? 0 : 1;\\n    d[i][j] = Math.min(d[i-1][j]+1, d[i][j-1]+1, d[i-1][j-1]+c);\\n    if(i>1 && j>1 && a[i-1]===b[j-2] && a[i-2]===b[j-1]) d[i][j] = Math.min(d[i][j], d[i-2][j-2]+1);\\n  }\\n  return d[a.length][b.length];\\n}\\nconst _merekCache = {};\\nfunction normMerek(m){\\n  const k = String(m||\'\').trim().toUpperCase().replace(/[^A-Z0-9 ]/g,\'\').replace(/\\\\s+/g,\' \').trim();\\n  if(!k) return \'LAINNYA\';\\n  if(_merekCache[k]) return _merekCache[k];\\n  let r = k;\\n  const first = k.split(\' \')[0];\\n  if(MEREK_KNOWN.includes(k)) r = k;\\n  else if(MEREK_ALIAS[k]) r = MEREK_ALIAS[k];\\n  else if(MEREK_KNOWN.includes(first)) r = first;\\n  else if(MEREK_ALIAS[first]) r = MEREK_ALIAS[first];\\n  else {\\n    // salah ketik: cari merek asli terdekat (huruf tertukar/kurang/lebih/salah)\\n    const max = k.length <= 2 ? 0 : k.length <= 4 ? 1 : k.length <= 7 ? 2 : 3;\\n    const cands = MEREK_KNOWN.concat(Object.keys(MEREK_ALIAS).filter(a => a.length >= 5));\\n    let best = null, bd = 99, tie = false;\\n    cands.forEach(b => {\\n      if(Math.abs(b.length - k.length) > max) return;\\n      const d = merekDist(k, b), to = MEREK_ALIAS[b] || b;\\n      if(d < bd){ bd = d; best = to; tie = false; } else if(d === bd && to !== best) tie = true;\\n    });\\n    if(best && bd <= max && !tie) r = best;\\n  }\\n  return (_merekCache[k] = r);\\n}\\nfunction autoFixMerek(){\\n  let n = 0;\\n  (DATA.stock || []).forEach(s => { if(!String(s.merek||\'\').trim()) return; const v = normMerek(s.merek); if(v !== s.merek){ s.merek = v; n++; } });\\n  return n;\\n}"], ["async function persist(){\\n  const okLocal = writeLocal();", "async function persist(){\\n  autoFixMerek();\\n  const okLocal = writeLocal();"], ["    if(j.data){ applyLoaded(j.data); writeLocal(); }", "    let _fixedMerek = 0;\\n    if(j.data){ applyLoaded(j.data); _fixedMerek = autoFixMerek(); writeLocal(); }"], ["    render(); startPolling();\\n    syncBadge(\'ok\', \'Tersimpan di VPS\');\\n    return;", "    render(); startPolling();\\n    syncBadge(\'ok\', \'Tersimpan di VPS\');\\n    if(_fixedMerek){ writeLocal(); await pushServer(); showToast(_fixedMerek + \' nama merek salah ketik dirapikan otomatis\'); }\\n    return;"]]')
for i, (old, new) in enumerate(EDITS, 1):
    n = src.count(old)
    if n != 1:
        print("0003: edit %d tidak cocok (ditemukan %d) - dibatalkan" % (i, n)); sys.exit(2)
    src = src.replace(old, new)
if crlf: src = src.replace("\n", "\r\n")
open(path, "w", encoding="utf-8").write(src)
print("0003: koreksi merek otomatis terpasang")
